-- Streak qualification rules:
--   Exercise session: >= 30 minutes duration
--   Steps day: >= 7,500 steps
-- A workout_post qualifies if it meets either threshold.

create or replace function update_streak_on_workout()
returns trigger language plpgsql security definer as $$
declare
  v_last_date date;
  v_current   integer;
  v_longest   integer;
  v_qualifies boolean;
begin
  -- Check if this workout meets the streak threshold
  v_qualifies := (
    -- Exercise session >= 30 min
    (new.activity_type != 'ganga' AND coalesce(new.duration_minutes, 0) >= 30)
    OR
    -- Steps >= 7,500 (steps tracked as 'ganga' with steps column)
    (new.activity_type = 'ganga' AND coalesce(new.steps, 0) >= 7500)
    OR
    -- Non-steps walking/hiking with >= 30 min duration
    (new.activity_type = 'ganga' AND coalesce(new.duration_minutes, 0) >= 30 AND coalesce(new.steps, 0) = 0)
  );

  if not v_qualifies then
    return new;
  end if;

  select last_active_date, current_streak, longest_streak
    into v_last_date, v_current, v_longest
    from user_streaks
   where user_id = new.user_id;

  if v_last_date is null or v_last_date < new.workout_date - interval '1 day' then
    v_current := 1;
  elsif v_last_date = new.workout_date - interval '1 day' then
    v_current := coalesce(v_current, 0) + 1;
  else
    -- Same day already counted
    return new;
  end if;

  v_longest := greatest(coalesce(v_longest, 0), v_current);

  insert into user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
  values (new.user_id, v_current, v_longest, new.workout_date, now())
  on conflict (user_id) do update
    set current_streak   = excluded.current_streak,
        longest_streak   = excluded.longest_streak,
        last_active_date = excluded.last_active_date,
        updated_at       = excluded.updated_at;

  return new;
end;
$$

-- 3. RPC: use a freeze — extends last_active_date to today so streak doesn't break
create or replace function use_streak_freeze(p_user_id uuid)
returns boolean language plpgsql security definer as $$
declare
  v_credits int;
  v_today   date := current_date;
  v_streak  user_streaks%rowtype;
begin
  select streak_freeze_credits into v_credits
  from profiles where id = p_user_id and is_pro = true;

  if v_credits is null or v_credits <= 0 then return false; end if;

  if exists (
    select 1 from streak_freeze_uses
    where user_id = p_user_id and freeze_date = v_today
  ) then return false; end if;

  select * into v_streak from user_streaks where user_id = p_user_id;

  insert into streak_freeze_uses (user_id, freeze_date) values (p_user_id, v_today);

  update profiles
  set streak_freeze_credits = streak_freeze_credits - 1
  where id = p_user_id;

  -- Extend last_active_date to today so tomorrow's workout still continues the streak
  insert into user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
  values (
    p_user_id,
    coalesce(v_streak.current_streak, 1),
    coalesce(v_streak.longest_streak, 1),
    v_today,
    now()
  )
  on conflict (user_id) do update
    set last_active_date = v_today,
        updated_at = now();

  return true;
end;
$$

