-- The insert trigger resets streak when steps are first inserted but below 7500.
-- When HC re-syncs later in the day with a higher step count it does an UPDATE,
-- not an INSERT, so the insert trigger never fires again. This trigger handles
-- that case: it awards the streak when steps cross the 7500 threshold on update.

create or replace function update_streak_on_step_update()
returns trigger language plpgsql security definer as $$
declare
  v_last_date date;
  v_current   integer;
  v_longest   integer;
begin
  -- Only handle step rows crossing the threshold
  if new.activity_type != 'ganga' then return new; end if;
  if coalesce(new.steps, 0) < 7500 then return new; end if;
  if coalesce(old.steps, 0) >= 7500 then return new; end if; -- already counted today

  select last_active_date, current_streak, longest_streak
    into v_last_date, v_current, v_longest
    from user_streaks
   where user_id = new.user_id;

  if v_last_date is null or v_last_date < new.workout_date::date - interval '1 day' then
    v_current := 1;
  elsif v_last_date = new.workout_date::date - interval '1 day' then
    v_current := coalesce(v_current, 0) + 1;
  else
    return new; -- same day already counted or workout_date is in the past beyond yesterday
  end if;

  v_longest := greatest(coalesce(v_longest, 0), v_current);

  insert into user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
  values (new.user_id, v_current, v_longest, new.workout_date::date, now())
  on conflict (user_id) do update
    set current_streak   = excluded.current_streak,
        longest_streak   = excluded.longest_streak,
        last_active_date = excluded.last_active_date,
        updated_at       = excluded.updated_at;

  return new;
end;
$$

create trigger on_step_update_streak
  after update of steps on workout_posts
  for each row execute function update_streak_on_step_update()

-- Fix 1: Atomic use_streak_freeze to prevent TOCTOU race condition.
--   Previous: SELECT credits → check → INSERT use → UPDATE credits  (two concurrent calls
--   could both read credits=1 and both proceed)
--   Fix: atomic UPDATE with WHERE credits > 0, then check ROW_COUNT.
--   The UNIQUE constraint on streak_freeze_uses rejects any second concurrent INSERT.

create or replace function use_streak_freeze(p_user_id uuid)
returns boolean language plpgsql security definer as $$
declare
  v_affected int;
  v_today    date := current_date;
  v_streak   user_streaks%rowtype;
begin
  -- Guard: already used a freeze today
  if exists (
    select 1 from streak_freeze_uses
    where user_id = p_user_id and freeze_date = v_today
  ) then return false; end if;

  -- Atomically decrement credits — only succeeds if user is Pro AND has credits left.
  -- This eliminates the SELECT-then-UPDATE race window.
  update profiles
  set streak_freeze_credits = streak_freeze_credits - 1
  where id = p_user_id
    and is_pro = true
    and streak_freeze_credits > 0;

  get diagnostics v_affected = row_count;
  if v_affected = 0 then return false; end if;

  -- Record the freeze day (UNIQUE constraint prevents duplicate on concurrent call)
  insert into streak_freeze_uses (user_id, freeze_date)
  values (p_user_id, v_today)
  on conflict (user_id, freeze_date) do nothing;

  -- Extend last_active_date to today so tomorrow's workout continues the streak
  select * into v_streak from user_streaks where user_id = p_user_id;

  insert into user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
  values (
    p_user_id,
    coalesce(v_streak.current_streak, 1),
    coalesce(v_streak.longest_streak, 1),
    v_today,
    now()
  )
  on conflict (user_id) do update
    set last_active_date = v_today,
        updated_at = now();

  return true;
end;
$$

-- Fix 2: Update streak qualification triggers to recognise 'walk' type with steps >= 7500.
--   Both Health Connect and HealthKit now sync step-based activities as activity_type='walk'
--   (not 'ganga'). Without this fix, step days never qualify for streaks.

create or replace function update_streak_on_workout()
returns trigger language plpgsql security definer as $$
declare
  v_last_date date;
  v_current   integer;
  v_longest   integer;
  v_qualifies boolean;
begin
  v_qualifies := (
    -- Exercise session >= 20 min (any type that is not purely steps-based)
    (new.activity_type not in ('ganga') AND coalesce(new.duration_minutes, 0) >= 20)
    OR
    -- Legacy 'ganga' step rows >= 7,500 steps
    (new.activity_type = 'ganga' AND coalesce(new.steps, 0) >= 7500)
    OR
    -- 'walk' type used by Health Connect / HealthKit step sync >= 7,500 steps
    (new.activity_type = 'walk' AND coalesce(new.steps, 0) >= 7500)
  );

  if not v_qualifies then
    return new;
  end if;

  select last_active_date, current_streak, longest_streak
    into v_last_date, v_current, v_longest
    from user_streaks
   where user_id = new.user_id;

  if v_last_date is null or v_last_date < new.workout_date - interval '1 day' then
    v_current := 1;
  elsif v_last_date = new.workout_date - interval '1 day' then
    v_current := coalesce(v_current, 0) + 1;
  else
    return new;
  end if;

  v_longest := greatest(coalesce(v_longest, 0), v_current);

  insert into user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
  values (new.user_id, v_current, v_longest, new.workout_date, now())
  on conflict (user_id) do update
    set current_streak   = excluded.current_streak,
        longest_streak   = excluded.longest_streak,
        last_active_date = excluded.last_active_date,
        updated_at       = excluded.updated_at;

  return new;
end;
$$

create or replace function update_streak_on_step_update()
returns trigger language plpgsql security definer as $$
declare
  v_last_date date;
  v_current   integer;
  v_longest   integer;
begin
  -- Handle both legacy 'ganga' and current 'walk' step rows
  if new.activity_type not in ('ganga', 'walk') then return new; end if;
  if coalesce(new.steps, 0) < 7500 then return new; end if;
  if coalesce(old.steps, 0) >= 7500 then return new; end if; -- already counted today

  select last_active_date, current_streak, longest_streak
    into v_last_date, v_current, v_longest
    from user_streaks
   where user_id = new.user_id;

  if v_last_date is null or v_last_date < new.workout_date::date - interval '1 day' then
    v_current := 1;
  elsif v_last_date = new.workout_date::date - interval '1 day' then
    v_current := coalesce(v_current, 0) + 1;
  else
    return new;
  end if;

  v_longest := greatest(coalesce(v_longest, 0), v_current);

  insert into user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
  values (new.user_id, v_current, v_longest, new.workout_date::date, now())
  on conflict (user_id) do update
    set current_streak   = excluded.current_streak,
        longest_streak   = excluded.longest_streak,
        last_active_date = excluded.last_active_date,
        updated_at       = excluded.updated_at;

  return new;
end;
$$

-- ─── Step 2: Backfill — run until all recurring chains have an active/upcoming instance ──

DO $$
DECLARE
  pass INTEGER := 0;
  max_passes INTEGER := 100; -- safety cap (weekly × years)
BEGIN
  -- Run process_recurring_challenges repeatedly until no more gaps exist.
  -- Each pass advances every expired chain by one period. With weekly challenges
  -- and gaps of up to ~2 years, this converges in ≤ 104 passes.
  LOOP
    pass := pass + 1;
    EXIT WHEN pass > max_passes;

    PERFORM process_recurring_challenges();

    -- Stop when every recurring chain has an active or upcoming leaf
    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM fitness_challenges fc
      WHERE fc.renewal_type != 'none'
        AND fc.status = 'completed'
        AND NOT EXISTS (
          SELECT 1 FROM fitness_challenges child
          WHERE child.parent_challenge_id = fc.id
        )
    );
  END LOOP;

  RAISE NOTICE 'Backfill complete in % pass(es)', pass;
END;
$$

-- Fix IDOR vulnerability in use_streak_freeze RPC.
-- The original function accepted an arbitrary p_user_id without verifying that
-- the caller is the same user, allowing any authenticated user to burn another
-- user's streak-freeze credits.  This replacement adds an auth.uid() guard as
-- the very first statement in the function body.

create or replace function use_streak_freeze(p_user_id uuid)
returns boolean language plpgsql security definer as $$
declare
  v_credits int;
  v_today   date := current_date;
  v_streak  user_streaks%rowtype;
begin
  -- SECURITY: caller must be the user whose freeze is being consumed.
  if auth.uid() is distinct from p_user_id then
    raise exception 'unauthorized';
  end if;

  select streak_freeze_credits into v_credits
  from profiles where id = p_user_id and is_pro = true;

  if v_credits is null or v_credits <= 0 then return false; end if;

  if exists (
    select 1 from streak_freeze_uses
    where user_id = p_user_id and freeze_date = v_today
  ) then return false; end if;

  select * into v_streak from user_streaks where user_id = p_user_id;

  insert into streak_freeze_uses (user_id, freeze_date) values (p_user_id, v_today);

  update profiles
  set streak_freeze_credits = streak_freeze_credits - 1
  where id = p_user_id;

  -- Extend last_active_date to today so tomorrow's workout still continues the streak.
  insert into user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
  values (
    p_user_id,
    coalesce(v_streak.current_streak, 1),
    coalesce(v_streak.longest_streak, 1),
    v_today,
    now()
  )
  on conflict (user_id) do update
    set last_active_date = v_today,
        updated_at = now();

  return true;
end;
$$

-- Part B: rebuild award_global_points_on_workout with the fan-out guard
CREATE OR REPLACE FUNCTION award_global_points_on_workout()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_pts integer := 1;
BEGIN
  -- Skip fan-out copies: they share the same real workout as the original row.
  -- Awarding points here would multiply global points by the number of active
  -- challenges the user is enrolled in.
  IF NEW.parent_workout_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Standard scoring: 1 pt per workout + 1 per 1 000 steps + 1 per km + 1 per 30 min
  IF NEW.steps IS NOT NULL THEN
    v_pts := v_pts + floor(NEW.steps / 1000.0)::integer;
  END IF;
  IF NEW.distance_km IS NOT NULL THEN
    v_pts := v_pts + floor(NEW.distance_km)::integer;
  END IF;
  IF NEW.duration_minutes IS NOT NULL THEN
    v_pts := v_pts + floor(NEW.duration_minutes / 30.0)::integer;
  END IF;

  UPDATE profiles
  SET    total_points = COALESCE(total_points, 0) + v_pts
  WHERE  id = NEW.user_id;

  RETURN NEW;
END;
$$

-- Emergency least-privilege fix for backend-only OAuth token RPCs.
-- No function bodies, table rows, keys, tokens or user data are changed.
-- Requires the live device_token_rpcs definitions; do not replay unrelated local
-- migrations against production to satisfy this prerequisite.
BEGIN;
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '15s';
REVOKE EXECUTE ON FUNCTION public.find_garmin_pending(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.find_garmin_pending(text) TO service_role;
REVOKE EXECUTE ON FUNCTION public.get_device_connection_decrypted(text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_device_connection_decrypted(text,text) TO service_role;
REVOKE EXECUTE ON FUNCTION public.update_encrypted_device_tokens(uuid,text,text,text,timestamp with time zone) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.update_encrypted_device_tokens(uuid,text,text,text,timestamp with time zone) TO service_role;
REVOKE EXECUTE ON FUNCTION public.upsert_encrypted_device_tokens(uuid,text,text,text,text,timestamp with time zone,boolean,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.upsert_encrypted_device_tokens(uuid,text,text,text,text,timestamp with time zone,boolean,text) TO service_role;

DO $$
DECLARE signature text;
BEGIN
  FOREACH signature IN ARRAY ARRAY[
    'public.find_garmin_pending(text)',
    'public.get_device_connection_decrypted(text,text)',
    'public.update_encrypted_device_tokens(uuid,text,text,text,timestamp with time zone)',
    'public.upsert_encrypted_device_tokens(uuid,text,text,text,text,timestamp with time zone,boolean,text)'
  ] LOOP
    IF has_function_privilege('anon', signature, 'EXECUTE')
       OR has_function_privilege('authenticated', signature, 'EXECUTE')
       OR NOT has_function_privilege('service_role', signature, 'EXECUTE') THEN
      RAISE EXCEPTION 'Unexpected token RPC privileges: %', signature;
    END IF;
  END LOOP;
END $$;
COMMIT;

-- Preserve owner reads/deletes and native-health upserts, but keep OAuth
-- credentials and provider identities writable only by the backend.
BEGIN;
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '15s';

REVOKE ALL PRIVILEGES ON TABLE public.device_connections
  FROM PUBLIC, anon, authenticated;

-- Remove any independent column grants too; table revocation alone is not enough.
DO $acl$
DECLARE col text;
BEGIN
  FOR col IN SELECT attname FROM pg_attribute
    WHERE attrelid = 'public.device_connections'::regclass
      AND attnum > 0 AND NOT attisdropped
  LOOP
    EXECUTE format(
      'REVOKE ALL PRIVILEGES (%I) ON public.device_connections FROM PUBLIC, anon, authenticated', col);
  END LOOP;
END
$acl$;

-- SELECT remains table-wide for existing-client compatibility. RLS still scopes
-- reads and deletes to the owner; ciphertext visibility is a separate follow-up.
GRANT SELECT, DELETE ON public.device_connections TO authenticated;
GRANT INSERT (user_id, provider, is_active) ON public.device_connections TO authenticated;
GRANT UPDATE (user_id, provider, is_active, last_synced_at)
  ON public.device_connections TO authenticated;

-- PostgREST upsert updates every supplied field, including its conflict keys.
-- Permit same-value assignments but never move a credential-bearing row to a
-- different provider/owner. Use the actual SQL role, not client-editable claims.
CREATE FUNCTION public.guard_device_connection_identity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $guard$
BEGIN
  IF current_user IN ('anon', 'authenticated')
     AND (NEW.user_id IS DISTINCT FROM OLD.user_id
          OR NEW.provider IS DISTINCT FROM OLD.provider) THEN
    RAISE EXCEPTION 'Connection owner and provider cannot be changed by clients'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$guard$;
REVOKE ALL ON FUNCTION public.guard_device_connection_identity() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER guard_device_connection_identity
BEFORE UPDATE ON public.device_connections
FOR EACH ROW EXECUTE FUNCTION public.guard_device_connection_identity();

-- Exercise the guard on a disposable synthetic table, never real account rows.
CREATE TEMP TABLE connection_identity_probe (
  user_id uuid NOT NULL, provider text NOT NULL, is_active boolean,
  UNIQUE (user_id, provider)
) ON COMMIT DROP;
GRANT ALL ON pg_temp.connection_identity_probe TO authenticated;
CREATE TRIGGER guard_probe BEFORE UPDATE ON pg_temp.connection_identity_probe
FOR EACH ROW EXECUTE FUNCTION public.guard_device_connection_identity();
SET LOCAL ROLE authenticated;
INSERT INTO pg_temp.connection_identity_probe VALUES
  ('00000000-0000-4000-8000-000000000001', 'health_connect', false);
INSERT INTO pg_temp.connection_identity_probe VALUES
  ('00000000-0000-4000-8000-000000000001', 'health_connect', true)
ON CONFLICT (user_id, provider) DO UPDATE
SET user_id = excluded.user_id, provider = excluded.provider, is_active = excluded.is_active;
DO $probe$
BEGIN
  IF NOT (SELECT is_active FROM pg_temp.connection_identity_probe) THEN
    RAISE EXCEPTION 'Same-identity reconnect failed';
  END IF;
  BEGIN
    UPDATE pg_temp.connection_identity_probe SET provider = 'strava';
    RAISE EXCEPTION 'Provider reassignment was not blocked';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE pg_temp.connection_identity_probe
      SET user_id = '00000000-0000-4000-8000-000000000002';
    RAISE EXCEPTION 'Owner reassignment was not blocked';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END
$probe$;
RESET ROLE;

DO $verify$
DECLARE col text;
BEGIN
  FOR col IN SELECT attname FROM pg_attribute
    WHERE attrelid = 'public.device_connections'::regclass
      AND attnum > 0 AND NOT attisdropped
  LOOP
    IF has_column_privilege('anon', 'public.device_connections', col, 'SELECT')
       OR has_column_privilege('anon', 'public.device_connections', col, 'INSERT')
       OR has_column_privilege('anon', 'public.device_connections', col, 'UPDATE') THEN
      RAISE EXCEPTION 'Anonymous column privilege remains: %', col;
    END IF;
    IF has_column_privilege('authenticated', 'public.device_connections', col, 'INSERT')
         IS DISTINCT FROM (col = ANY(ARRAY['user_id','provider','is_active']))
       OR has_column_privilege('authenticated', 'public.device_connections', col, 'UPDATE')
         IS DISTINCT FROM (col = ANY(ARRAY['user_id','provider','is_active','last_synced_at'])) THEN
      RAISE EXCEPTION 'Unexpected client write privilege: %', col;
    END IF;
    IF NOT has_column_privilege('service_role', 'public.device_connections', col, 'INSERT')
       OR NOT has_column_privilege('service_role', 'public.device_connections', col, 'UPDATE') THEN
      RAISE EXCEPTION 'Backend write privilege missing: %', col;
    END IF;
  END LOOP;
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = 'public.device_connections'::regclass) THEN
    RAISE EXCEPTION 'Connection ownership RLS must remain enabled';
  END IF;
END
$verify$;
COMMIT;
